package com.collectiq.security;
import org.springframework.context.annotation.*;import org.springframework.security.config.Customizer;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.oauth2.core.*;import org.springframework.security.oauth2.jwt.*;import org.springframework.security.web.SecurityFilterChain;import org.springframework.web.cors.CorsConfiguration;import org.springframework.web.cors.CorsConfigurationSource;import org.springframework.web.cors.UrlBasedCorsConfigurationSource;import java.util.*;
@Configuration public class SecurityConfig{
 @Bean SecurityFilterChain security(HttpSecurity http)throws Exception{return http.csrf(c->c.disable()).cors(Customizer.withDefaults()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/actuator/health","/api/auth/**","/api/whatsapp/webhook").permitAll().anyRequest().authenticated()).oauth2ResourceServer(o->o.jwt(Customizer.withDefaults())).addFilterAfter(new TenantFilter(),org.springframework.security.oauth2.server.resource.web.authentication.BearerTokenAuthenticationFilter.class).build();}
 @Bean CorsConfigurationSource corsConfigurationSource(@org.springframework.beans.factory.annotation.Value("${CORS_ALLOWED_ORIGINS:http://localhost:3000}")String origins){CorsConfiguration c=new CorsConfiguration();c.setAllowedOrigins(Arrays.stream(origins.split(",")).map(String::trim).toList());c.setAllowedMethods(List.of("GET","POST","PUT","PATCH","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("Authorization","Content-Type","X-Requested-With"));c.setAllowCredentials(false);UrlBasedCorsConfigurationSource s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;}
 @Bean JwtDecoder jwtDecoder(@org.springframework.beans.factory.annotation.Value("${JWT_ISSUER_URI:https://accounts.google.com}")String issuer,@org.springframework.beans.factory.annotation.Value("${JWT_JWK_SET_URI:https://www.googleapis.com/oauth2/v3/certs}")String jwks,@org.springframework.beans.factory.annotation.Value("${GOOGLE_CLIENT_ID:}")String clientId){NimbusJwtDecoder d=NimbusJwtDecoder.withJwkSetUri(jwks).build();OAuth2TokenValidator<Jwt> issuerValidator=JwtValidators.createDefaultWithIssuer(issuer);OAuth2TokenValidator<Jwt> audienceValidator=jwt->!clientId.isBlank()&&jwt.getAudience().contains(clientId)?OAuth2TokenValidatorResult.success():OAuth2TokenValidatorResult.failure(new OAuth2Error("invalid_token","Google ID token audience mismatch",""));d.setJwtValidator(jwt->{OAuth2TokenValidatorResult v=issuerValidator.validate(jwt);return v.hasErrors()?v:audienceValidator.validate(jwt);});return d;}
}